import java.util.*

fun nextPermutation(idx: IntArray): Boolean {
    val n = idx.size
    for (i in n - 1 downTo 1) {
        if (idx[i] > idx[i - 1]) {
            val temp = idx[i]
            idx[i] = idx[i - 1]
            idx[i - 1] = temp
            val sub = idx.copyOfRange(i, n)
            sub.sort()
            System.arraycopy(sub, 0, idx, i, sub.size)
            return true
        }
    }
    return false
}

fun main() {
    val scanner = Scanner(System.`in`)
    val n = scanner.nextInt()
    val a = scanner.nextInt()
    val b = scanner.nextInt()

    val frames = IntArray(6)
    val idxs = IntArray(6)
    for (i in 0 until 6) {
        frames[i] = if (i < 4) a else b
        idxs[i] = i
    }

    var bestAnswer = 6
    while (true) {
        var count = 0
        var leftover = 0
        for (i in 0 until 6) {
            if (leftover < frames[idxs[i]]) {
                count++
                leftover = n
            }
            leftover -= frames[idxs[i]]
        }
        if (count < bestAnswer) {
            bestAnswer = count
        }
        if (!nextPermutation(idxs)) {
            break
        }
    }

    println(bestAnswer)
}
